"use strict";
const animeTopics=[
 {id:'conan-secret',from:1996,series:'名侦探柯南',title:'如果是你，会不会把秘密告诉小兰？',question:'一个知道真相的人，会比什么都不知道更安心，还是更危险？',intro:'只讨论早期设定：少年侦探遇到神秘黑衣人，身体变小；不带入后续组织身份或结局。',choices:['先保密，等有足够把握','找一个安全的时机坦白','还要再观察几集'],source:'https://www.ytv.co.jp/conan/archive/k19960902.html',notes:['我看到这里最在意的，反而不是下一集会发生什么案件，而是熟悉的人就在身边，却有一句话怎么也说不出口。假如告诉她真相，故事也许会轻松一点，但危险会不会跟着靠近？','也有人会觉得，越是在乎一个人，越不该替她做所有决定。知道真相以后，她也许能帮忙留意线索。可这只是站在屏幕外面的想法，身在其中的时候，恐怕没有这么容易。','本楼只设想早期观众能讨论的问题，不讨论组织成员的后续身份，不给出后来剧情的答案。先记下今天的猜测，保留等下一集时那种悬着的心情。']},
 {id:'naruto-family',from:2003,series:'火影忍者',title:'鸣人的身世，会不会藏在村子的过去里？',question:'只凭早期人物关系和村里人的态度，你会怎样猜？',intro:'以早期动画设定和中忍考试时期为范围，不提供后来公开的身世答案。',choices:['和某位前辈有联系','关键在村子的那次事件','线索还不够，继续等更新'],source:'https://naruto-official.com/anime/naruto1',notes:['我总觉得，村里人看他的眼神不只是害怕。有些人像是知道什么，却没有把话说完。一个孩子想得到大家认可，这一点很明白；但他自己不了解的过去，也许会影响后面的故事。','如果只按早期画面来猜，我会去比较人物的动作、习惯和被刻意省略的对话。相似并不能证明关系，可追番时的乐趣，正是把这样的小线索抄到本子上，再和朋友争一争。','也可能我们想得太复杂了。编剧只是想先写一个孤单的少年，怎样一点点找到同伴。无论答案是什么，我都更想看他在下一次比赛里，怎样让别人认真记住他的名字。']},
 {id:'naruto-mask',from:2003,series:'火影忍者',title:'卡卡西为什么总戴着面罩？来开一个脑洞楼',question:'认真推理一分钟，剩下的时间允许胡思乱想。',intro:'只围绕早期外观设定开脑洞，不展示后来的揭面剧情或官方答案。',choices:['只是个人习惯','有一段不想提的经历','说不定就是为了让人好奇'],source:'https://naruto-official.com/anime/naruto1',notes:['不知道你们有没有这种感觉：越是不让看的东西，就越想知道。明明战斗和任务都很紧张，课间聊起来的时候，我们却总会绕回那个很小的问题——他到底为什么戴着面罩？','可以猜得很认真，也可以完全不认真。有人会从忍者的习惯出发，有人会编出一段过去，还有人觉得，保持一点神秘就挺好，不知道反而能聊很久。','如果你已经知道后来发生了什么，今天先把答案放一边。假装下课铃刚响，身边的人还只看到了同样的几集，再写一个当时也能想出来的理由。']},
 {id:'onepiece-sky',from:2004,series:'航海王',title:'空岛的那些旧故事，会不会还有更远的回声？',question:'古老遗迹、传说和冒险，哪一种线索最值得记下来？',intro:'讨论范围到空岛篇，不使用后续篇章的名词、身份和揭示作为证据。',choices:['古老文字还会派上用场','先记住传说里的人和约定','这就是一次独立的大冒险'],source:'https://one-piece.com/anime/153/index.html',notes:['看完一段冒险以后，最让我舍不得翻篇的，常常不是最后谁赢了，而是那些古老的约定。遗迹里留下的东西，好像只讲了一半，另一半还在海的更远处等着。','如果这是一个普通的论坛，我大概会把觉得奇怪的台词摘成自己的笔记，画几条关系线，再标一个大大的问号。今天觉得无关紧要的细节，过几个月说不定就会让人一拍桌子。','也别把每样东西都当成伏笔。站在这一段故事结束的地方，单纯为那口钟、那段旅程和同伴之间的信任感动，也已经很值得。下一座岛会是什么样，我们一起慢慢猜。']},
 {id:'onepiece-crew',from:2000,series:'航海王',title:'如果船上再来一个同伴，你最想要什么职业？',question:'只从早期航海生活出发，给这艘船补一块拼图。',intro:'不列出后来实际加入的成员，不拿后续剧情当成今天的依据。',choices:['能照顾大家的职业','能解决船和航行问题的职业','能让旅程更热闹的职业'],source:'https://one-piece.com/anime/index.html',notes:['一艘船走得越远，要处理的事就越多。吃饭、看天气、照顾伤病、修理东西……光是想一想，就觉得这个故事能一直讲下去。','如果让你在不知道后续发展的情况下选一个新伙伴，你会先考虑“有用”，还是先考虑“合得来”？我大概会选那个能在大家都累了的时候，突然讲一个很烂的笑话的人。','这个楼没有标准答案，也不公布后来的名单。我们只是把自己喜欢的旅行方式，悄悄放进一艘想象中的船里。']},
 {id:'anime-notebook',from:1999,series:'放学杂谈',title:'你会把剧情猜测写在作业本最后一页吗？',question:'交换一个追番习惯，看看谁和你一样。',intro:'原创校园回忆讨论，不对应某个真实论坛的原帖。',choices:['画人物关系图','记下台词和下一集猜测','只在课间和朋友聊天'],source:'',notes:['作业本最后一页，总会留给和作业无关的事。有人在角落画人物，有人抄一段喜欢的台词，还有人认真列出三个理由，证明自己猜的那个结局一定会发生。','课间十分钟，足够把上一集重新讲一遍。你说这是伏笔，他说只是作画习惯，两个人谁也说服不了谁。铃一响，又把本子合起来，等到中午接着争。','很多猜测后来都没有猜中。但朋友趴在桌子上，指着那一小块纸讲得那么认真的样子，比真正的答案还更容易让人记住。']}
];
let animeTopic=null,animeChoices={},animeReplies={};
try{const p=JSON.parse(localStorage.getItem('archaeo-anime-club')||'{}');for(const t of animeTopics){if(Number.isInteger(p.choices?.[t.id])&&p.choices[t.id]>=0&&p.choices[t.id]<3)animeChoices[t.id]=p.choices[t.id];if(Array.isArray(p.replies?.[t.id]))animeReplies[t.id]=p.replies[t.id].filter(s=>typeof s==='string').slice(-12).map(s=>s.slice(0,500));}}catch{}
function saveAnime(){try{localStorage.setItem('archaeo-anime-club',JSON.stringify({choices:animeChoices,replies:animeReplies}));}catch{}}
function openAnimeClub(){animeTopic=null;navigate({type:'anime',name:'放学动漫社',url:'archaeo://anime'});}
function renderAnimeClub(){const available=animeTopics.filter(t=>t.from<=Number(year())),t=available.find(t=>t.id===animeTopic);return `<section class="anime-club"><div class="anime-club-top"><button data-action="home">‹ 时光首页</button><button data-anime-club>讨论区</button><button data-community="tianya">社区客厅</button><button data-capture-view>保存这一页</button></div><header><div><small>AFTER SCHOOL ANIME CLUB / 放学以后</small><h1>动漫放映社</h1><p>先别翻答案，来聊聊你的推测。</p><span>${year()} 年视角 · 保守限定讨论范围 · 原创模拟帖</span></div><button data-era-poster="anime"><img src="images/posters/anime.jpg" alt="原创动漫社怀旧画报"></button></header><div class="anime-spoiler-note">这里的讨论是新创作的年代体验，不冒充历史原帖。只使用对应年份以前可讨论的早期设定，不公布后来答案；各平台当年的引进进度可能不同。你的选择与回复仅本机可见。</div>${t?`<article class="anime-topic"><small>${escapeHTML(t.series)} / 猜测楼</small><h2>${escapeHTML(t.title)}</h2><p class="anime-scope">${escapeHTML(t.intro)}</p>${t.notes.map(p=>`<p>${escapeHTML(p)}</p>`).join('')}<section class="anime-vote"><h3>${escapeHTML(t.question)}</h3>${t.choices.map((c,i)=>`<button data-anime-vote="${i}" class="${animeChoices[t.id]===i?'selected':''}">${animeChoices[t.id]===i?'●':'○'} ${escapeHTML(c)}</button>`).join('')}<small>只记录你的选择，不显示虚构参与人数，也不公布“正确答案”。</small></section><div class="anime-replies">${(animeReplies[t.id]||[]).map((r,i)=>`<div><b>你的第 ${i+1} 条猜测</b><p>${escapeHTML(r)}</p><small>仅本机可见</small></div>`).join('')}</div><form id="anime-reply"><label for="anime-reply-text">把当时也能想到的猜测留在这里</label><textarea id="anime-reply-text" maxlength="500" required placeholder="先不说后来的答案，聊聊你看到这里的想法…"></textarea><button>保存本机猜测</button></form>${t.source?`<a class="anime-source" href="${t.source}" target="_blank" rel="noopener noreferrer">作品官方资料 ↗（外部页面可能含最新信息）</a>`:''}</article>`:`<div class="anime-topic-grid">${available.map(t=>`<button data-anime-topic="${t.id}"><span>${t.series}</span><h2>${escapeHTML(t.title)}</h2><p>${escapeHTML(t.intro)}</p><b>进楼聊聊 &gt;&gt;</b></button>`).join('')||'<p>目前最早的体验帖从1996年开始，可以换一年再来看看。</p>'}</div>`}</section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-anime-club],[data-anime-topic],[data-anime-vote]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-anime-club'))return openAnimeClub();if(b.dataset.animeTopic&&animeTopics.some(t=>t.id===b.dataset.animeTopic&&t.from<=Number(year()))){animeTopic=b.dataset.animeTopic;navigate(current,false);}if(b.dataset.animeVote!==undefined&&animeTopics.some(t=>t.id===animeTopic)){const n=Number(b.dataset.animeVote);if(Number.isInteger(n)&&n>=0&&n<3){animeChoices[animeTopic]=n;saveAnime();navigate(current,false);}}});
document.addEventListener('submit',e=>{if(e.target.id!=='anime-reply')return;e.preventDefault();if(!animeTopics.some(t=>t.id===animeTopic))return;const text=$('#anime-reply-text').value.trim().slice(0,500);if(!text)return;animeReplies[animeTopic]=[...(animeReplies[animeTopic]||[]),text].slice(-12);saveAnime();navigate(current,false);toast('已保存你的本机猜测');});
